CREATE TABLE IF NOT EXISTS public.guidance_inquiries (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, sells TEXT NOT NULL, customers TEXT, goals JSONB NOT NULL DEFAULT '[]'::jsonb, budget TEXT, digital_presence TEXT, name TEXT NOT NULL, whatsapp TEXT NOT NULL, notes TEXT, source_page TEXT, referrer TEXT, ip_address TEXT, user_agent TEXT, status TEXT NOT NULL DEFAULT 'new', admin_notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());